//! Profiles built from what the account's models are, and what a quick test showed they do.
//!
//! A profile is a main model (Everyday chat) plus the model of every other route. Four are
//! generated by requirement — smartest, fastest, cheapest, balanced — from the ranking Meo API
//! attaches to chat models and from probe results (which models really answer, how fast). A model
//! that failed its probe is never chosen; one never probed is judged by its ranking alone.

use std::collections::HashMap;

use super::{
    api::{Model, Probe, Rank},
    router::{self, Choice},
};

pub const MAX_PROBES_PER_CONNECTION: usize = 8;

pub fn probe_key(credential: &str, model: &str) -> String {
    format!("{credential}|{model}")
}

/// The server's ranking when it sends one; otherwise the same idea from the model id (older
/// servers): small names (mini, flash, haiku, ...) are fast and cheap, pro/opus/max names are
/// smart, and a newer generation in the id ranks higher.
fn rank(m: &Model) -> Rank {
    if let Some(r) = &m.rank {
        return r.clone();
    }
    let id = m.id.to_lowercase();
    let word = |w: &str| {
        id.match_indices(w)
            .any(|(i, _)| i == 0 || !id.as_bytes()[i - 1].is_ascii_alphabetic())
    };
    let small = [
        "mini", "nano", "lite", "flash", "haiku", "small", "turbo", "instant",
    ]
    .iter()
    .any(|w| word(w));
    let big = [
        "opus", "pro", "ultra", "max", "reasoner", "thinking", "large",
    ]
    .iter()
    .any(|w| word(w));
    // First version in the id (not a date or a size): "gpt-5.1" 5.1, "claude-opus-4-8" 4.8.
    let tokens: Vec<&str> = id
        .split(|c: char| !(c.is_ascii_digit() || c == '.' || c == '-'))
        .flat_map(|chunk| chunk.split('-'))
        .filter(|t| !t.is_empty())
        .collect();
    let small_number = |t: &str| t.len() <= 2 && t.chars().all(|c| c.is_ascii_digit());
    let generation = tokens
        .iter()
        .position(|t| t.len() <= 3 && t.parse::<f64>().is_ok())
        .map(|i| {
            let major: f64 = tokens[i].parse().unwrap_or(0.0);
            match tokens.get(i + 1) {
                Some(next) if major.fract() == 0.0 && next.len() == 1 && small_number(next) => {
                    major + next.parse::<f64>().unwrap_or(0.0) / 10.0
                }
                _ => major,
            }
        })
        .unwrap_or(0.0);
    let (tier, base, speed, cost) = if small {
        ("small", 46.0, 90, 85)
    } else if big {
        ("flagship", 80.0, 40, 25)
    } else {
        ("standard", 64.0, 65, 55)
    };
    let intelligence = (base + (generation * 2.2).min(14.0) - 14.0).clamp(0.0, 100.0) as u32;
    Rank {
        tier: tier.into(),
        generation,
        intelligence,
        speed,
        cost,
        balanced: (intelligence as f64 * 0.5 + speed as f64 * 0.25 + cost as f64 * 0.25) as u32,
    }
}

fn is_chat(m: &Model) -> bool {
    m.task == "chat"
}

/// A model one would pick as the main chat model: conversational, not an audio/realtime or
/// coding-agent specialist that the catalogue happens to label "chat".
fn is_general(m: &Model) -> bool {
    let id = m.id.to_lowercase();
    is_chat(m)
        && ![
            "audio",
            "realtime",
            "codex",
            "search-preview",
            "deep-research",
            "transcribe",
            "tts",
        ]
        .iter()
        .any(|w| id.contains(w))
}

/// "claude-opus-4-8" → "claude": models of one family are alike, so tests should span families.
fn family(id: &str) -> String {
    id.to_lowercase()
        .chars()
        .take_while(|c| c.is_ascii_alphabetic())
        .collect()
}

/// A speed figure where a measurement beats the guess: 1 s is 90, 5 s is 50.
fn speed(m: &Model, probe: Option<&Probe>) -> i64 {
    match probe {
        Some(p) if p.ok => 100 - (p.latency_ms / 100).min(99) as i64,
        _ => rank(m).speed as i64,
    }
}

type Entry<'a> = (&'a String, &'a Model, Option<&'a Probe>);

fn usable<'a>(models: &'a [(String, Model)], probes: &'a HashMap<String, Probe>) -> Vec<Entry<'a>> {
    models
        .iter()
        .filter(|(_, m)| is_general(m))
        .map(|(c, m)| (c, m, probes.get(&probe_key(c, &m.id))))
        .filter(|(_, _, p)| p.is_none_or(|p| p.ok))
        .collect()
}

fn pool_of<'a>(list: &[Entry<'a>], all: &[Entry<'a>]) -> Vec<Entry<'a>> {
    if list.is_empty() {
        all.to_vec()
    } else {
        list.to_vec()
    }
}

fn with_images<'a>(list: &[Entry<'a>]) -> Vec<Entry<'a>> {
    list.iter()
        .copied()
        .filter(|e| e.1.input.iter().any(|i| i == "image"))
        .collect()
}

fn best<'a>(entries: &[Entry<'a>], key: impl Fn(&Entry<'a>) -> (i64, i64)) -> Option<Choice> {
    entries
        .iter()
        .max_by(|a, b| key(a).cmp(&key(b)).then_with(|| b.1.id.cmp(&a.1.id)))
        .map(|(c, m, _)| ((*c).clone(), m.id.clone()))
}

/// Models worth testing on one connection (at most 8): the smartest, the fastest, the cheapest.
pub fn candidates_to_probe(models: &[Model]) -> Vec<String> {
    let chat: Vec<&Model> = models.iter().filter(|m| is_general(m)).collect();
    let mut out: Vec<String> = Vec::new();
    // The best few by one measure, each from a different family, so a test covers the field.
    let mut take = |mut list: Vec<&Model>, n: usize, f: &dyn Fn(&Rank) -> u32| {
        list.sort_by(|a, b| {
            f(&rank(b))
                .cmp(&f(&rank(a)))
                .then_with(|| b.id.len().cmp(&a.id.len()).reverse())
                .then_with(|| a.id.cmp(&b.id))
        });
        let mut families: Vec<String> = Vec::new();
        for m in list {
            if families.len() >= n || out.len() >= MAX_PROBES_PER_CONNECTION {
                break;
            }
            let fam = family(&m.id);
            if !families.contains(&fam) && !out.contains(&m.id) {
                families.push(fam);
                out.push(m.id.clone());
            }
        }
    };
    take(chat.clone(), 3, &|r| r.intelligence);
    take(chat.clone(), 3, &|r| r.speed);
    take(chat, 2, &|r| r.cost);
    out
}

/// `(id, name, slots)` of the four requirement profiles; empty when no chat model is usable.
pub fn requirement_profiles(
    models: &[(String, Model)],
    probes: &HashMap<String, Probe>,
) -> Vec<(String, String, HashMap<String, Choice>)> {
    let entries = usable(models, probes);
    if entries.is_empty() {
        return Vec::new();
    }
    // Image, video, speech and the like: the usual automatic choice.
    let base = router::suggest(models);
    let intel = |e: &Entry| rank(e.1).intelligence as i64;
    let lat = |e: &Entry| {
        -e.2.filter(|p| p.ok)
            .map_or(i64::MAX / 4, |p| p.latency_ms as i64)
    };
    let smart_floor: Vec<Entry> = entries.iter().copied().filter(|e| intel(e) >= 55).collect();
    let capable: Vec<Entry> = entries.iter().copied().filter(|e| intel(e) >= 35).collect();
    let smartest = best(&entries, |e| (intel(e), lat(e)));
    let fastest_any = best(&capable, |e| (speed(e.1, e.2), intel(e)));

    let build =
        |id: &str, name: &str, main: Option<Choice>, vision_key: &dyn Fn(&Entry) -> (i64, i64)| {
            let main = main?;
            let mut slots = base.clone();
            slots.insert("default".into(), main);
            if let Some(c) = fastest_any.clone() {
                slots.insert("fast".into(), c);
            }
            if let Some(c) = smartest.clone() {
                slots.insert("thinking".into(), c);
            }
            if let Some(c) = best(&with_images(&entries), |e| vision_key(e)) {
                slots.insert("vision".into(), c);
            }
            Some((format!("req:{id}"), name.to_owned(), slots))
        };
    let balanced = |e: &Entry| (rank(e.1).balanced as i64, lat(e));
    let cheapest = |e: &Entry| (rank(e.1).cost as i64, intel(e));
    let fastest = |e: &Entry| (speed(e.1, e.2), intel(e));
    let smartest_key = |e: &Entry| (intel(e), lat(e));
    [
        build("smartest", "Smartest", smartest.clone(), &smartest_key),
        build("fastest", "Fastest", best(&capable, fastest), &fastest),
        build(
            "cheapest",
            "Cheapest",
            best(&pool_of(&smart_floor, &entries), cheapest),
            &cheapest,
        ),
        build(
            "balanced",
            "Balanced",
            best(&pool_of(&smart_floor, &entries), balanced),
            &balanced,
        ),
    ]
    .into_iter()
    .flatten()
    .collect()
}

/// Chat models best first: usable ones by intelligence, untested and failed ones after.
pub fn ranked(
    models: &[(String, Model)],
    probes: &HashMap<String, Probe>,
) -> Vec<(String, Model, Option<Probe>)> {
    let mut rows: Vec<(String, Model, Option<Probe>)> = models
        .iter()
        .filter(|(_, m)| is_chat(m))
        .map(|(c, m)| {
            (
                c.clone(),
                m.clone(),
                probes.get(&probe_key(c, &m.id)).cloned(),
            )
        })
        .collect();
    rows.sort_by(|a, b| {
        let failed = |r: &(String, Model, Option<Probe>)| r.2.as_ref().is_some_and(|p| !p.ok);
        failed(a)
            .cmp(&failed(b))
            .then_with(|| rank(&b.1).intelligence.cmp(&rank(&a.1).intelligence))
            .then_with(|| a.1.id.cmp(&b.1.id))
    });
    rows
}

#[cfg(test)]
mod tests {
    use super::*;

    fn model(
        id: &str,
        tier: &str,
        intelligence: u32,
        speed: u32,
        cost: u32,
        image: bool,
    ) -> (String, Model) {
        (
            "c1".into(),
            Model {
                id: id.into(),
                name: id.into(),
                task: "chat".into(),
                tasks: vec!["chat".into()],
                input: if image {
                    vec!["text".into(), "image".into()]
                } else {
                    vec!["text".into()]
                },
                output: vec!["text".into()],
                rank: Some(Rank {
                    tier: tier.into(),
                    generation: 4.0,
                    intelligence,
                    speed,
                    cost,
                    balanced: (intelligence + speed + cost) / 3,
                }),
            },
        )
    }

    fn catalogue() -> Vec<(String, Model)> {
        vec![
            model("big", "flagship", 80, 30, 20, true),
            model("mid", "standard", 62, 65, 55, true),
            model("tiny", "small", 42, 92, 88, false),
        ]
    }

    fn slot(p: &(String, String, HashMap<String, Choice>), route: &str) -> String {
        p.2[route].1.clone()
    }

    #[test]
    fn requirement_profiles_pick_a_main_model_by_what_the_user_wants() {
        let all = requirement_profiles(&catalogue(), &HashMap::new());
        let by = |id: &str| all.iter().find(|p| p.0 == format!("req:{id}")).unwrap();
        assert_eq!(slot(by("smartest"), "default"), "big");
        assert_eq!(slot(by("fastest"), "default"), "tiny");
        assert_eq!(
            slot(by("cheapest"), "default"),
            "mid",
            "cheapest still has to be smart enough"
        );
        assert_eq!(slot(by("balanced"), "default"), "mid");
        assert_eq!(slot(by("fastest"), "thinking"), "big");
        assert_eq!(slot(by("smartest"), "fast"), "tiny");
        assert_eq!(
            slot(by("fastest"), "vision"),
            "mid",
            "vision needs a model that takes images"
        );
    }

    #[test]
    fn a_failed_probe_removes_a_model_and_a_measurement_beats_the_guess() {
        let mut probes = HashMap::new();
        probes.insert(
            probe_key("c1", "big"),
            Probe {
                ok: false,
                latency_ms: 30_000,
            },
        );
        let all = requirement_profiles(&catalogue(), &probes);
        let smartest = all.iter().find(|p| p.0 == "req:smartest").unwrap();
        assert_eq!(slot(smartest, "default"), "mid");
        probes.insert(
            probe_key("c1", "tiny"),
            Probe {
                ok: true,
                latency_ms: 9_000,
            },
        );
        probes.insert(
            probe_key("c1", "mid"),
            Probe {
                ok: true,
                latency_ms: 700,
            },
        );
        let all = requirement_profiles(&catalogue(), &probes);
        let fastest = all.iter().find(|p| p.0 == "req:fastest").unwrap();
        assert_eq!(
            slot(fastest, "default"),
            "mid",
            "the model that answered in 0.7 s wins"
        );
    }

    #[test]
    fn without_a_server_ranking_the_id_decides() {
        let m = |id: &str| Model {
            id: id.into(),
            name: id.into(),
            task: "chat".into(),
            tasks: vec![],
            input: vec![],
            output: vec![],
            rank: None,
        };
        assert_eq!(
            rank(&m("gemini-3.5-pro")).tier,
            "flagship",
            "gemini contains mini but is not small"
        );
        assert_eq!(rank(&m("gemini-3.5-flash")).tier, "small");
        assert_eq!(rank(&m("claude-sonnet-4-5")).tier, "standard");
        assert!(
            rank(&m("claude-opus-4-8")).intelligence > rank(&m("claude-sonnet-4-5")).intelligence
        );
        assert!(rank(&m("gpt-5-mini")).speed > rank(&m("gpt-5.1")).speed);
        assert!(rank(&m("gpt-5.1")).generation > 5.0);
    }

    #[test]
    fn nothing_usable_means_no_profile() {
        let mut probes = HashMap::new();
        for id in ["big", "mid", "tiny"] {
            probes.insert(
                probe_key("c1", id),
                Probe {
                    ok: false,
                    latency_ms: 1,
                },
            );
        }
        assert!(requirement_profiles(&catalogue(), &probes).is_empty());
        assert!(requirement_profiles(&[], &HashMap::new()).is_empty());
    }

    #[test]
    fn probe_candidates_cover_smart_fast_and_cheap_without_repeats() {
        let models: Vec<Model> = catalogue().into_iter().map(|(_, m)| m).collect();
        assert_eq!(candidates_to_probe(&models), ["big", "mid", "tiny"]);
        let many: Vec<Model> = (0..30)
            .map(|i| model(&format!("m{i}"), "standard", 40 + i, 90 - i, i, false).1)
            .collect();
        let picked = candidates_to_probe(&many);
        assert!(picked.len() <= MAX_PROBES_PER_CONNECTION);
        assert_eq!(
            picked.len(),
            picked
                .iter()
                .collect::<std::collections::HashSet<_>>()
                .len()
        );
    }

    #[test]
    fn ranking_puts_failed_models_last() {
        let mut probes = HashMap::new();
        probes.insert(
            probe_key("c1", "big"),
            Probe {
                ok: false,
                latency_ms: 1,
            },
        );
        let order: Vec<String> = ranked(&catalogue(), &probes)
            .into_iter()
            .map(|r| r.1.id)
            .collect();
        assert_eq!(order, ["mid", "tiny", "big"]);
    }
}
